window.DOZ_DATA_PARTS["mechanics-guides"] = {"guides":[{"title":"抽卡前先看懂三类保证","category":"抽卡","summary":"基础概率、目标保证与新手十次保证，解决的是不同问题。","sections":[{"title":"基础稀有度","paragraphs":["当前常规召唤帮助页和阿尔法召唤帮助页均写明：常规60%、稀有35%、独特5%。安装包还保留一份67%／30%／3%的旧文字；这份旧文字未作为当前召唤池的概率依据。","同为独特盟友不代表每个角色等概率。活动加成、条件分支和目标保证都可能改变具体角色的出现比例。"]},{"title":"目标保证","paragraphs":["部分阿尔法活动帮助页明确说明：抽到独特盟友时，有50%的可能是该池目标；如果得到另一个独特盟友，下一个独特盟友必为目标。","这只保证下一次独特结果的身份，没有在这句话中保证多少抽一定出现独特盟友。不能把所有关联活动盟友的配置都当成50%目标池。"]},{"title":"新手保证","paragraphs":["新手召唤帮助页明确写明：进行10次召唤，至少获得拉维奥夫人、瑞秋·普玛或安娜·帕夫洛娃博士中的一位独特盟友。","新手池单次标价100编码器，十连标价800编码器。新手活动可用时间和召唤次数有限；请查看游戏中的剩余次数和倒计时。"]},{"title":"单抽与十连","paragraphs":["常规和阿尔法召唤的单次标价是100对应编码器；十连原价1000、活动价900，活动折扣生效时平均每次90。是否启用活动价以召唤按钮为准。","资料没有证明十连本身能提高稀有度概率。折扣、十次新手保证和特殊活动保证应分开判断。"]},{"title":"仍待确认","paragraphs":["奖励链中存在多组有条件的独特权重，但完整的概率递增阈值、固定抽数保证、触发后的计数重置和跨活动继承尚未完成验证。不能因为说明页没有列出，就说游戏没有这些机制。","阿尔法编码器在活动结束后不会消失，可以留到之后的限时活动。编码器能保留不等于抽卡计数或目标保证状态必定跨池继承。"]}]},{"title":"乐透与翻牌：先算整轮预算","category":"抽卡","summary":"翻牌成本逐步变化；排除、已领取和刷新会改变奖池状态。","sections":[{"title":"一轮的开始与结束","paragraphs":["原版乐透说明包含选择三个奖品、已排除、已获得和剩余奖品状态。多数配置也记录三个排除名额；具体活动应以自己的窗口为准。","刷新会让已获得和已排除的奖品重新可用。清空一轮后可以刷新重新开始，因此不能把每次翻牌理解为不受历史结果影响的独立抽奖。"]},{"title":"如何读费用表","paragraphs":["每个奖池下方列出翻牌基础费用和累计费用。不同版本的同名奖池也可能有不同奖励或消耗。","累计值只是所列费用的算术和；额外上限、折扣和活动覆写未确认，所以它是预算参考，不是最终扣费承诺。刷新价格与自然刷新周期单独列出。"]},{"title":"怎样判断中奖率","paragraphs":["牌面看起来相似，并不表示所有奖励等概率。奖励配置中存在不同权重及多层奖励组合。","本资料不把单条权重直接当百分比，也不把1÷剩余牌数当稀有奖概率。先确认你想要的物品确实在该轮奖励中，再判断继续翻牌的花费是否可以接受。"]}]},{"title":"宝箱：分组概率与单件掉率","category":"抽卡","summary":"一个箱子可能同时发多个奖励组，分组百分比不能相加。","sections":[{"title":"为什么会有多个100%","paragraphs":["部分宝箱提示常规组100%、另一稀有度组也100%。它表达的是不同奖励组，不是互斥的单抽稀有度分布。","例如黑帮货物家族拥有多组奖励数量提示。看见某组100%，只能按该分组说明理解，不能推断某一把传奇武器必出。"]},{"title":"如何使用奖励清单","paragraphs":["宝箱清单沿原版奖励关系展开，包括候选物品和子项数量范围。组合选择、任务状态和其他条件可能限制实际发放。","现实货币宝箱不显示安装包中的历史金额。价格、地区货币、促销和是否上架由当前游戏商店确定。"]}]},{"title":"出征前的生存检查","category":"生存","summary":"先准备补给、区域防护和回收方案，再考虑带多少火力。","sections":[{"title":"能量、饥渴与补给","paragraphs":["当你在地图上移动、收集资源、搜索目标或激活隐形 时，都会消耗能量值。","即使你处于离线状态，你的角色能量值也会逐渐恢 复。一旦能量值满格，你将收到通知。","能量值会自动恢复。进食、使用神器、或者在你安全的避难所呆一段时间都可以恢复能量值。","食物和药品可恢复生命值。你可以在壁炉上做饭，也可以在治疗师桌上制作医疗用品。","新手奖励可以减缓饥饿和口渴的速度，并持续到21级。注意你角色的状况，适时使用食物和饮料。"]},{"title":"辐射和持续伤害","paragraphs":["如果角色受到辐射，生命值会下降。注意你的辐射等 级，及时使用抗辐射药物或其他药物。地形越危 险，辐射就越强。","某些武器、异象和燃烧物体可能会让你着火。你将受到周期性的火焰伤害。要扑灭火焰，请使用小型灭火器，它们可于伏击中在莱科维奇那里找到，或在被围困的房屋找到。","送葬者之屋和蛇彭特新娘营地的空气充满了酸性烟 雾，不断造成伤害。你需要压缩空气罐。你可以制作它们，也可以在领地或丹巴拉的盒子中找到它们。","森林之子的武器、肉食性树根和森林野兽的致命苔藓会造成毒素伤害。只有少数几种方法可以生存：使用猫鼬注射枪、吸附剂神器和森林游荡者铠甲。"]},{"title":"死亡后的物品","paragraphs":["如果你死亡，你的物品会损耗并失去一些耐用性。请查看你死亡后弹出的窗口，了解要在哪里领取你的物品。","死后收集物品时要当心！如果在拿起容器之前再次死亡，你将永远失去财物。","如果你在合作模式的地点死亡，留下的物品将返回避难所，并失去部分耐用性。","如果你在方舟中死亡，你的物品不会消耗（耐用的背包除外）。你会回到避难所。你的物品会留在要塞前哨的设施入口处。"]},{"title":"背包与基地","paragraphs":["普通的袋子无法装下很多战利品。提高等级，改善避难所的工作台来制作更宽大的背包。","地下室是你避难所最安全的地点，你可以在此找到修理工作台等有用的工作台。完成故事剧情任务以解锁地下室。","在游荡者营地，你可以做好准备前往异常区、和团队的商人交易，洗个澡或者将装备放进保险箱。"]}]},{"title":"武器、铠甲与伤害类型","category":"战斗","summary":"面板攻击只是起点，还要看伤害类型、目标防护与特殊能力。","sections":[{"title":"直接伤害和持续伤害","paragraphs":["特殊伤害有两部分。直接伤害由武器本身造成。周期性伤害会随着时间的推移影响敌人，例如燃烧或电击。","有些物品只增加武器的周期性伤害，另一些物品只增加其直接伤害。专属装备会增加武器的两种异象伤害。","该特效可无视铠甲并造成持续伤害，如出血或灼伤。小型灭火器等特殊装备和消耗品可以提供对此效果的防护。","这些由研究所开发的纳米机器会暂时为普通武器增加异象伤害，但对具有特殊伤害的武器不起作用。可作为完成派系任务的奖励获得。"]},{"title":"根据敌人选武器","paragraphs":["铠甲焦尸和食尸鬼易受酸性武器伤害。你可以在送葬者营地制作酸性武器。核判官的坟墓火焰也可熔化铠甲。","屠夫在吞噬了火焰异象后，获得了从火焰伤害恢复生命值的能力。但是，他容易受到寒冷武器的伤害。","送葬者的骨制铠甲对酸免疫。要轻松破坏它，你只能使用造成范围伤害的爆炸性武器，例如手榴弹或爆裂糖果。","变异的性质使得森林之子极易受到食尸鬼的血腥武器造成的重伤的伤害。"]},{"title":"战斗中的位置与节奏","paragraphs":["避开长舌僵尸的红色攻击区。如果被长舌僵尸用触手击中，它们的生命值将会恢复。","如果你退出战斗，精英敌人和一些头目不会跟随你。他们将返回其原始位置，并完全恢复生命值。","敌人在某些障碍物（例如铁栅）后面可能会着火，但它们受到的任何武器的伤害会降低。打开笼子即可造成全部伤害。","完美武器的自动能力在充能后会自动激活，可在装备的武器图标上看到能力状态。"]},{"title":"头目机制优先于硬拼","paragraphs":["僵尸守卫有双重生命值。他会在两根血条都耗尽时死亡。当心他的特殊攻击！这个头目会将你击晕。","鼠王会吞噬遗体以恢复生命值。尽量不要让头目靠近遗体。","枢机主教会召唤恶魔之烛来恢复他的生命值。尽快破坏它们。"]}]},{"title":"耐久、修理与长期养成","category":"养成","summary":"保住高价值装备，按工作台能力安排修理与制作。","sections":[{"title":"什么时候修","paragraphs":["你可以在铠甲或武器损坏之前修复它们。使用避难所地下室的快速修复工作台。","修理更高级别的铠甲或武器需要更高等级的工作台，还需要更多的工具和武器箱。","修复常见、罕见、传奇武器和铠甲需要不同的升级箱和工具。你可以在黄色和红色危险区的商人处获取。"]},{"title":"降低损耗","paragraphs":["铠甲修理箱\n\n赋予你被动防卫能力：铠甲修理。降低衣服和铠甲的磨损 率。","武器修理箱\n\n赋予你被动防卫能力：武器修理。降低武器的磨损 率。","图鉴中的装备数值来自安装包基础配置，实际表现还会受到角色成长、装备级别、套装、技能和当前效果影响。"]},{"title":"技能与装饰","paragraphs":["向技能量表投入技能点数以打开奖赏箱。箱中包含奖赏给角色的武器、铠甲、其他贵重物品和额外生命值点数！","要重置掌握的技能并获得你投入它们的技能点数，请点击红色的“技能重置”按钮。技能量表将完全重置。","相同的避难所装饰的效果可叠加四次。安装多个希望雕像，以进一步增加火焰武器造成的伤害。"]},{"title":"工具与制作","paragraphs":["你需要木板、废金属和混凝土来生产许多物品。在物品创建窗口中制作斧头和临时锤子，加速资源收集。","清除仓库障碍物需要使用镐，你可以在游荡者营地的维因处购买，也可以自己制作。","你需要撬锁工具才能打开门和箱子的锁。没有3级或4级撬锁工具也无法进入仓库监狱。你可以制作撬锁工具或者与维因交易获得。","在有些剧情任务中，你可以研究蓝图来制作独特的物品。"]}]},{"title":"盟友：组队、能量与成长","category":"盟友","summary":"把等级、级别和能量分开管理，避免只按力量数值选择队伍。","sections":[{"title":"团队和仓位","paragraphs":["使用第三个标签页来创建盟友团队。一个团队最多可以有4个盟友。","升级盟友基地的档案，增加总部和预备队的名额。","你也可以使用黄金来扩张总部和预备队，请点击最后一个预备队栏位中或总部上方面板中的+号按钮。","使用第二个标签页增加等级、提升级别或遣散盟友。点击锁定图标可防止盟友被遣散。"]},{"title":"能量决定持续作战","paragraphs":["盟友进行攻击或使用能力时会消耗能量。当他们没有外出或战斗时，能量会逐渐恢复。能量也可以在能量强化器的帮助下补充。","如果盟友的能量低，他们的被动能力就不会起作用。你可以通过点击数值中的+按钮来补充能量。","首领天赋需要该盟友的能量高于20%才能激活。","在侦察期间，你的盟友会损失能量值和物品耐用性。他们将无法进行任何行动，直到返回。"]},{"title":"数值分别看什么","paragraphs":["攻击力表示盟友普通攻击的每秒伤害，不含暴击；暴击几率与暴击伤害分别决定触发频率和倍数。","精通影响盟友能力效率；伤害加成会把你的武器每秒伤害的一部分加入盟友攻击力。准确性对应固定目标，反应对应移动目标。","装备可以提升盟友的数值。你可以在物品的描述中看到使用该物品的要求。"]},{"title":"级别与等级上限","paragraphs":["安装包中盟友级别1至6的等级上限依次为20、40、60、80、100、120。级别和当前等级是两个独立的成长维度。","锁定重要盟友可避免误遣散。侦察中的盟友不能随意调整，等其返回后再整理队伍和装备。"]},{"title":"编码器来源","paragraphs":["使用编码器来召唤盟友。你可以从盟友召唤控制器中得到它们，或者与基拉交易而获得。","普通编码器、小队编码器与阿尔法编码器是不同资源。小队编码器物品存在于安装包，但本次召唤模式表未找到其当前启用池，因此不编造它的抽卡费率或概率。"]}]}]};
